  `machine_type` int DEFAULT NULL,
  `no_of_machines` varchar(255) DEFAULT NULL,
  `cost_code` varchar(255) DEFAULT NULL,
  `cost_description` varchar(255) DEFAULT NULL,
  `piece_rate_type` varchar(255) DEFAULT NULL,
  `active` int NOT NULL DEFAULT '1',
  `updated_by` int DEFAULT NULL,
  `updated_date_time` datetime DEFAULT NULL,
  PRIMARY KEY (`designation_id`),
  KEY `idx_designation_branch_id` (`branch_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1689 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
