--
-- Table structure for table `drcr_note`
--

DROP TABLE IF EXISTS `drcr_note`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `drcr_note` (
  `debit_credit_note_id` int NOT NULL AUTO_INCREMENT,
  `date` date DEFAULT NULL,
  `adjustment_type` int DEFAULT NULL,
  `inward_id` int DEFAULT NULL,
  `remarks` varchar(255) DEFAULT NULL,
  `status_id` int DEFAULT NULL,
  `auto_create` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `updated_date_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `approved_by` int DEFAULT NULL,
  `approved_date` date DEFAULT NULL,
  `gross_amount` double DEFAULT NULL,
  `net_amount` double DEFAULT NULL,
  `round_off_value` double DEFAULT NULL,
  PRIMARY KEY (`debit_credit_note_id`),
  KEY `inward_id` (`inward_id`),
  KEY `status_id` (`status_id`),
  CONSTRAINT `drcr_note_ibfk_1` FOREIGN KEY (`inward_id`) REFERENCES `proc_inward` (`inward_id`),
  CONSTRAINT `drcr_note_ibfk_2` FOREIGN KEY (`status_id`) REFERENCES `status_mst` (`status_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
