  `passport_no` varchar(20) DEFAULT NULL,
  `driving_licence_no` varchar(50) DEFAULT NULL,
  `pan_no` varchar(15) DEFAULT NULL,
  `aadhar_no` varchar(20) DEFAULT NULL,
  `branch_id` bigint NOT NULL,
  `updated_by` int DEFAULT NULL,
